from __future__ import annotations

__doc__ = """
Optional CuPy-backed ADAAs and coefficient backend definitions.

The module exports ``PROVIDE_CUPY`` together with the backend and ADAA classes.
When CuPy is not installed, the ADAA classes are omitted and only the feature
flag remains available.
"""

from typing import Any

import numpy as np

from ....adaa import ComplexArrayADAA, ImagArrayADAA, RealArrayADAA
from ....coeffbackend import CoeffBackend

PROVIDE_CUPY = False

try:
    import cupy as cp
except Exception:
    cp = None
else:
    try:
        cp.cuda.runtime.getDeviceCount()
    except Exception:
        cp = None
    else:
        PROVIDE_CUPY = True


if PROVIDE_CUPY:

    class CuPyCoeffBackend(CoeffBackend):
        """Coefficient backend storing arrays as CuPy device arrays."""

        def coeff_new_array(self, size: int, dtype: str):
            match dtype:
                case "f32":
                    return cp.zeros(size, dtype=cp.float32)
                case "f64":
                    return cp.zeros(size, dtype=cp.float64)
                case "i32":
                    return cp.zeros(size, dtype=cp.int32)
                case "i64":
                    return cp.zeros(size, dtype=cp.int64)
                case _:
                    raise ValueError(f"dtype {dtype} not understood")

        def coeff_from_numpy(
            self,
            coeff_like: Any,
            nparray: np.ndarray,
            size: int,
            dtype: str,
        ) -> None:
            del size
            if dtype in ("f32", "f64"):
                if nparray.dtype in [np.float32, np.float64]:
                    coeff_like[:] = cp.asarray(np.ascontiguousarray(nparray))
                else:
                    raise ValueError(
                        f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                    )
            elif dtype in ("i32", "i64"):
                if nparray.dtype in [np.int32, np.int64]:
                    coeff_like[:] = cp.asarray(np.ascontiguousarray(nparray))
                else:
                    raise ValueError(
                        f"Wrong input datatype {nparray.dtype} for dtype {dtype}."
                    )
            else:
                raise ValueError(f"dtype {dtype} not understood")

        def coeff_to_numpy(
            self, coeff_like: Any, size: int, dtype: str
        ) -> np.ndarray:
            del size
            match dtype:
                case "f32":
                    return np.array(cp.asnumpy(coeff_like), dtype=np.float32)
                case "f64":
                    return np.array(cp.asnumpy(coeff_like), dtype=np.float64)
                case "i32":
                    return np.array(cp.asnumpy(coeff_like), dtype=np.int32)
                case "i64":
                    return np.array(cp.asnumpy(coeff_like), dtype=np.int64)
                case _:
                    raise ValueError(f"dtype {dtype} not understood")

        def coeff_to_zero(self, coeff_like: Any, size: int, dtype: str):
            del size, dtype
            coeff_like.fill(0)

        def coeff_linop(
            self,
            arr_r: Any,
            /,
            scal_a: float | None,
            arr_x: Any,
            scal_b: float | None,
            arr_y: Any,
            *,
            size: int,
            dtype: str,
            inplace: bool = False,
        ):
            del size, dtype
            if arr_r is None:
                return
            if not inplace and arr_x is None:
                arr_r[:] = 0
            elif arr_x is not None:
                match (inplace, scal_a):
                    case (True, None):
                        arr_r[:] += arr_x
                    case (True, scal_a):
                        arr_r[:] += scal_a * arr_x
                    case (False, None):
                        arr_r[:] = arr_x
                    case (False, scal_a):
                        arr_r[:] = scal_a * arr_x

            match (scal_b, arr_y):
                case (None, None):
                    return
                case (_, None):
                    return
                case (None, arr_y):
                    arr_r[:] += arr_y
                case (scal_b, arr_y):
                    arr_r[:] += scal_b * arr_y


    class CupyCA(
        ComplexArrayADAA,
        backend=CuPyCoeffBackend(),
        identifier="CUPY",
        is_anchor=True,
    ):
        """Complex ADAA backed by CuPy device arrays."""


    class CupyRA(
        RealArrayADAA,
        backend=CuPyCoeffBackend(),
        identifier="CUPY",
        is_anchor=True,
    ):
        """Real ADAA backed by CuPy device arrays."""


    class CupyIA(
        ImagArrayADAA,
        backend=CuPyCoeffBackend(),
        identifier="CUPY",
        is_anchor=True,
    ):
        """Purely imaginary ADAA backed by CuPy device arrays."""


    __all__ = [
        "PROVIDE_CUPY",
        "CuPyCoeffBackend",
        "CupyCA",
        "CupyRA",
        "CupyIA",
    ]
else:
    __all__ = ["PROVIDE_CUPY"]
